def project(balance, rate, years):
    for year in range(years):
        balance = balance * (1 + rate)
    return balance

def project_saving(balance, rate, years, deposit):
    for year in range(years):
        balance = balance * (1 + rate)
        balance = balance + deposit
    return balance

with open("prices.csv", "w") as f:
    f.write("Day,Close\nMon,101.20\nTue,102.50\nWed,99.80\nThu,100.40\nFri,101.10\n")

def daily_return(p0, p1):
    return (p1 - p0) / p0

def returns_from_file(name):
    closes = []
    for line in open(name).readlines()[1:]:
        closes.append(float(line.split(",")[1]))
    returns = []
    for i in range(1, len(closes)):
        returns.append(daily_return(closes[i - 1], closes[i]))
    return returns

for r in returns_from_file("prices.csv"):
    print(f"{r:.2%}")
